-- Meridian Museum schema (MySQL 8+)
CREATE TABLE PERSON(PersonID BIGINT PRIMARY KEY, FirstName VARCHAR(80), MiddleName VARCHAR(80), LastName VARCHAR(80));
CREATE TABLE ORGANIZATION(OrgID BIGINT PRIMARY KEY, OrgName VARCHAR(200) NOT NULL);
CREATE TABLE PERSON_PHONE(PersonID BIGINT NOT NULL, Phone VARCHAR(30) NOT NULL, PRIMARY KEY(PersonID,Phone), FOREIGN KEY(PersonID) REFERENCES PERSON(PersonID));
CREATE TABLE LENDER(PersonID BIGINT PRIMARY KEY, LenderType VARCHAR(30), FOREIGN KEY(PersonID) REFERENCES PERSON(PersonID));
CREATE TABLE EMPLOYEE(PersonID BIGINT PRIMARY KEY, Role VARCHAR(30), FOREIGN KEY(PersonID) REFERENCES PERSON(PersonID));
CREATE TABLE CURATOR(PersonID BIGINT PRIMARY KEY, Specialty VARCHAR(100), FOREIGN KEY(PersonID) REFERENCES EMPLOYEE(PersonID));
CREATE TABLE REGISTRAR(PersonID BIGINT PRIMARY KEY, Department VARCHAR(100), FOREIGN KEY(PersonID) REFERENCES EMPLOYEE(PersonID));
CREATE TABLE ARTIFACT(ArtifactID BIGINT PRIMARY KEY, CatalogNo VARCHAR(50) UNIQUE, Title VARCHAR(200), CollectionType VARCHAR(80));
CREATE TABLE LOAN(LoanID BIGINT PRIMARY KEY, LenderID BIGINT NOT NULL, StartDate DATE NOT NULL, ExpiryDate DATE NOT NULL, ReturnDate DATE, Status VARCHAR(30), CHECK(ExpiryDate >= StartDate), FOREIGN KEY(LenderID) REFERENCES LENDER(PersonID));
CREATE TABLE LOAN_OBJECT(LoanID BIGINT NOT NULL, ArtifactID BIGINT NOT NULL, AgreedValue DECIMAL(12,2), ReceivedCondition TEXT, ReturnedCondition TEXT, PRIMARY KEY(LoanID,ArtifactID), FOREIGN KEY(LoanID) REFERENCES LOAN(LoanID), FOREIGN KEY(ArtifactID) REFERENCES ARTIFACT(ArtifactID));
CREATE TABLE EXHIBITION(ExhibitionID BIGINT PRIMARY KEY, ExhibitionName VARCHAR(200), StartDate DATE, EndDate DATE);
CREATE TABLE DISPLAY_SLOT(ExhibitionID BIGINT NOT NULL, SlotNo INT NOT NULL, SlotLabel VARCHAR(100), PRIMARY KEY(ExhibitionID,SlotNo), FOREIGN KEY(ExhibitionID) REFERENCES EXHIBITION(ExhibitionID));
CREATE TABLE CONDITION_REPORT(ReportID BIGINT PRIMARY KEY, ArtifactID BIGINT NOT NULL, LoanID BIGINT, ReportDate DATE NOT NULL, Notes TEXT, FOREIGN KEY(ArtifactID) REFERENCES ARTIFACT(ArtifactID), FOREIGN KEY(LoanID) REFERENCES LOAN(LoanID));
CREATE TABLE ARTIFACT_OWNERSHIP(ArtifactID BIGINT NOT NULL, OwnerType VARCHAR(20) NOT NULL, OwnerID BIGINT NOT NULL, Share DECIMAL(5,2) NOT NULL, ValidFrom DATE NOT NULL, ValidTo DATE, PRIMARY KEY(ArtifactID,OwnerType,OwnerID,ValidFrom), CHECK(Share>0 AND Share<=100), FOREIGN KEY(ArtifactID) REFERENCES ARTIFACT(ArtifactID));
